#include "TypingPerformance.h"
static void testTyping(const File& root){
    TypingCapture capture;std::vector<Note> notes={{0,1,60,.8f}};double length=99;
    expect(capture.phrase(1000,120,notes,length).failed()&&notes.size()==1&&length==99,"empty retrospective recall leaves caller output unchanged");
    capture.noteOn(60,.25f,1000);capture.noteOn(64,.75f,1250);capture.noteOff(60,2000);capture.noteOff(64,2250);
    expect(capture.phrase(2500,120,notes,length).wasOk()&&notes.size()==2&&length==4&&notes[0].beat==0&&notes[0].length==2&&notes[1].beat==.5&&notes[1].length==2&&notes[0].velocity==.25f&&notes[1].velocity==.75f,"retrospective notes retain chord offsets, durations and individual velocities at current tempo");
    expect(capture.phrase(2500,60,notes,length).wasOk()&&notes[0].length==1&&notes[1].beat==.25,"retrospective wall-clock timing converts using recall tempo");
    capture.clear();capture.noteOn(72,.5f,0);capture.noteOff(72,100000);
    expect(capture.phrase(100000,300,notes,length).wasOk()&&notes.size()==1&&notes[0].beat==0&&notes[0].length==64&&length==64,"long held notes clip to the latest 64-beat capture window at fast tempo");
    expect(capture.phrase(161000,120,notes,length).failed(),"completed performances expire after sixty seconds of inactivity");
    capture.clear();capture.noteOn(60,.5f,100);capture.noteOn(60,.7f,600);capture.allOff(1100);
    expect(capture.phrase(1100,120,notes,length).wasOk()&&notes.size()==2&&notes[0].length==1&&notes[1].beat==1&&notes[1].velocity==.7f,"rearticulating a pitch closes its prior event instead of losing the phrase");
    capture.clear();capture.noteOn(67,.9f,1000);expect(capture.phrase(2000,120,notes,length).wasOk()&&notes[0].length==2,"held notes are included up to recall time without mutating history");capture.noteOff(67,3000);expect(capture.phrase(3000,120,notes,length).wasOk()&&notes[0].length==4,"later release retains full duration after a read-only preview");
    capture.clear();capture.noteOn(-1,.5f,0);capture.noteOn(128,.5f,0);capture.noteOn(60,std::numeric_limits<float>::quiet_NaN(),0);capture.noteOn(60,.5f,std::numeric_limits<double>::infinity());expect(capture.size()==0,"invalid input pitches, velocity and times cannot poison capture");
    for(int i=0;i<1000;++i){capture.noteOn(60,.5f,i*10);capture.noteOff(60,i*10+5);}expect(capture.size()==TypingCapture::capacity,"performance memory has a fixed 512-event limit");expect(capture.phrase(10000,120,notes,length).wasOk()&&notes.size()==512&&notes.front().beat==0&&notes.back().beat<11,"full capture retains the most recent events and reanchors at zero");
    auto retained=notes;auto priorLength=length;expect(capture.phrase(10000,std::numeric_limits<double>::quiet_NaN(),notes,length).failed()&&notes==retained&&length==priorLength,"invalid recall tempo is atomic");capture.clear();expect(capture.size()==0&&capture.phrase(10000,120,notes,length).failed(),"clear forgets completed and held performance history");
    capture.noteOn(60,.5f,0);capture.noteOff(60,500);expect(capture.setWindow(15000)&&capture.phrase(16000,120,notes,length).failed(),"selected capture window excludes older notes");capture.expire(16000);expect(capture.size()==0&&!capture.setWindow(61000),"idle expiration clears old stored notes and rejects an excessive history window");
    auto file=root.getChildFile("typing-preferences.json");TypingSettings settings{45,6,false};expect(saveTypingSettings(file,settings).wasOk(),"typing preferences save locally");TypingSettings restored;expect(loadTypingSettings(file,restored).wasOk()&&restored.velocity==45&&restored.octave==6&&!restored.enabled,"velocity, octave and enable preference roundtrip independently of projects");
    auto before=file.loadFileAsString();expect(saveTypingSettings(file,{128,4,true}).failed()&&file.loadFileAsString()==before,"invalid preference writes preserve the existing file");file.replaceWithText(R"({"schema":1,"velocity":0,"octave":4,"enabled":true})");expect(loadTypingSettings(file,restored).failed()&&restored.velocity==45&&restored.octave==6&&!restored.enabled,"invalid preference reads retain all prior settings atomically");
    file.replaceWithText(R"({"schema":1,"velocity":64.5,"octave":4,"enabled":true})");expect(loadTypingSettings(file,restored).failed(),"fractional velocities are rejected instead of silently truncated");
    settings={80,3,true,-7,false,15};expect(saveTypingSettings(file,settings).wasOk()&&loadTypingSettings(file,restored).wasOk()&&restored.transpose==-7&&!restored.capture&&restored.captureSeconds==15,"transposition, capture switch and window persist with keyboard preferences");file.replaceWithText(R"({"schema":1,"velocity":102,"octave":4,"enabled":true})");expect(loadTypingSettings(file,restored).wasOk()&&restored.transpose==0&&restored.capture&&restored.captureSeconds==60,"earlier keyboard preference files gain safe neutral extension defaults");
    Assets assets;auto song=emptyProject();song.master=.3f;song.tracks[7].send=0;song.tracks[7].volume=.1f;song.tracks[7].release=.02f;
    auto quiet=makeEngine(song,assets,root),loud=makeEngine(song,assets,root);quiet->playing.store(false);loud->playing.store(false);quiet->audition(7,60,true,.25f);loud->audition(7,60,true,.75f);AudioBuffer<float> a(2,2048),b(2,2048);quiet->render(a.getWritePointer(0),a.getWritePointer(1),2048);loud->render(b.getWritePointer(0),b.getWritePointer(1),2048);float ratio=b.getRMSLevel(0,0,2048)/a.getRMSLevel(0,0,2048);expect(std::abs(ratio-3)<.01f,"configured input velocity changes actual rendered audio amplitude");
    auto engine=makeEngine(song,assets,root);engine->playing.store(false);bool accepted=true;for(int i=0;i<128;++i)accepted&=engine->audition(7,60,true);expect(accepted&&!engine->audition(7,60,false),"bounded audition queue reports a lost note-off at capacity");engine->auditionPanicRequested.store(true);for(int i=0;i<10;++i)engine->render(a.getWritePointer(0),a.getWritePointer(1),2048);expect(!engine->auditionPanicRequested.load()&&a.getMagnitude(0,0,2048)<.000001f,"emergency note release drains queued onsets and silences their voices instead of sticking");
}
